  }
  .grid{
    display:grid;
    grid-template-columns:1fr 1fr 1fr;
    grid-template-rows:auto;
  }
  .cell{
    border-right:var(--bar) solid var(--black);
    border-bottom:var(--bar) solid var(--black);
    padding:2.2rem 2rem;
    min-height:100%;
  }
  .cell:last-child{border-right:none;}
  .cell.red{background:var(--red);color:var(--white);}
  .cell.blue{background:var(--blue);color:var(--white);}
  .cell.yellow{background:var(--yellow);color:var(--black);}
